out=Path('docs/research/workshop-pass6/yamaha-rear-wheel');dep=Path('docs/research/frame-pass3/rear-wheel-remove-refit-v1.procedure.json');p=json.loads(dep.read_text(encoding='utf8'));old=copy.deepcopy(p['steps']);url=p['source']['source_url']
def step(id,title,text,pages,check,record=False,diagram=True):return {'id':id,'title':title,'instruction':text,'source_pdf_pages':pages,'verification':[check],'record_required':record,'diagram_reference_required':diagram,'source_links':[url+f'#page={n}' for n in pages] if diagram else [],'origin':'Original OEM-based summary; labeled storage, inspection records and conservative new sprocket nuts are explicit workflow adaptations.'}
