p['required_parts']=[{'name':n,'purpose':v} for n,v in [('Three exact matching new rear-wheel bearings','One right and two left, PDF135/137; no catalog part numbers inferred.'),('Two exact matching new oil seals','Approximate1mm recess; marks outward.'),('One new matching rear-wheel bearing circlip','Right-side retention, PDF135/137.'),('Six matching new sprocket self-locking nuts','Conservative renewal choice for this workflow; source specifies self-locking nuts and42Nm, not an inferred chemical grade.'),('Lithium-soap-based grease','Seal lips and rear axle.'),('LOCTITE locking agent','Disc bolt threads; actual product recorded, grade unspecified by source.')]]
